+func TestCmdNameCompletionInGo(t *testing.T) {
+	rootCmd := &Command{
+		Use: "root",
+		Run: emptyRun,
+	}
+	childCmd1 := &Command{
+		Use:   "firstChild",
+		Short: "First command",
+		Run:   emptyRun,
+	}
+	childCmd2 := &Command{
+		Use: "secondChild",
+		Run: emptyRun,
+	}
+	hiddenCmd := &Command{
+		Use:    "testHidden",
+		Hidden: true, // Not completed
+		Run:    emptyRun,
+	}
+	deprecatedCmd := &Command{
+		Use:        "testDeprecated",
+		Deprecated: "deprecated", // Not completed
+		Run:        emptyRun,
+	}
+	aliasedCmd := &Command{
+		Use:     "aliased",
+		Short:   "A command with aliases",
+		Aliases: []string{"testAlias", "testSynonym"}, // Not completed
+		Run:     emptyRun,
+	}
+
+	rootCmd.AddCommand(childCmd1, childCmd2, hiddenCmd, deprecatedCmd, aliasedCmd)
+
+	// Test that sub-command names are completed
+	output, err := executeCommand(rootCmd, ShellCompNoDescRequestCmd, "")
+	if err != nil {
+		t.Errorf("Unexpected error: %v", err)
+	}
+
+	expected := strings.Join([]string{
+		"aliased",
+		"completion",
+		"firstChild",
+		"help",
+		"secondChild",
+		":4",
+		"Completion ended with directive: ShellCompDirectiveNoFileComp", ""}, "\n")
